    this.errorDetail,
    this.errorCode,
  });

  @override
  int get hashCode =>
      data.hashCode ^
      errorKind.hashCode ^
      errorDetail.hashCode ^
      errorCode.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VideoTagsResult &&
          runtimeType == other.runtimeType &&
          data == other.data &&
          errorKind == other.errorKind &&
          errorDetail == other.errorDetail &&
          errorCode == other.errorCode;
}
